#include SDK_HEADER
#ifdef __cplusplus
#define SDK_ASSERT static_assert
#else
#define SDK_ASSERT _Static_assert
#endif
SDK_ASSERT(MAELYS_DATALOG_PUBLIC_ALLOW_NONE == 0u, "NONE is permanently zero");
SDK_ASSERT((MAELYS_DATALOG_PUBLIC_ALLOW_NONE | MAELYS_DATALOG_PUBLIC_ALLOW_TEST_ONLY)
           == MAELYS_DATALOG_PUBLIC_ALLOW_TEST_ONLY, "NONE is OR-neutral");
SDK_ASSERT((MAELYS_DATALOG_PUBLIC_ALLOW_NONE | MAELYS_DATALOG_PUBLIC_ALLOW_UNDECLARED_POLICY_ATOMS)
           == MAELYS_DATALOG_PUBLIC_ALLOW_UNDECLARED_POLICY_ATOMS, "NONE is OR-neutral");
int main(void) { return 0; }
